const [a,b]=await Promise.all([d.result(),e.result()]);return [a,b].map(x=>read(x.ref));

// Children already opened for the three judgments; wait for them.
const rs = {};
for (const id of ['n2','n3','n4']) rs[id] = await nodes.handle(id).result();
return rs;

